#!/bin/bash
set -eo pipefail
umask 077
test "$(id -un)" = sunyiq
for parent in / /data1 /data1/home /data1/home/sunyiq; do
  test -d "$parent"
  test ! -L "$parent"
  test "$(readlink -e "$parent")" = "$parent"
done
test ! -e '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001'
test ! -L '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001'
mkdir '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001'
mkdir '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/contracts'
mkdir '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/logs'
mkdir '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/references'
mkdir '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/src'
set -o noclobber
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/src/source_format_runtime_v1.py'
printf '%s  %s\n' 'd2017cd10fc3d75850deb449efd3ba9400ec1312db5a6114414ec288c05c6de0' '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/src/source_format_runtime_v1.py' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/contracts/FIRST_SOURCE_SIGNATURE_v1.json'
printf '%s  %s\n' 'df9b800c1a44c555007261909da71583c7d583c78fcba54b3b44e86f03ef5b95' '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/contracts/FIRST_SOURCE_SIGNATURE_v1.json' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/references/EXACT_SOURCE_SCHEMA_v1.json'
printf '%s  %s\n' 'd537fbd12a904c69645f269b2221b34cda12cebf69247865c03662aca2be8306' '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/references/EXACT_SOURCE_SCHEMA_v1.json' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/format_v1.sbatch'
printf '%s  %s\n' '04b2d9c168ea78fcad4082659ea2929952e693fc18f7f934d20f122c15c241a3' '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/format_v1.sbatch' | sha256sum -c -
job=$(sbatch --parsable '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/format_v1.sbatch')
case "$job" in ''|*[!0-9]*) exit 1;; esac
printf '%s\n' "$job" > '/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001/job_id.txt'
printf 'FORMAT_ROOT=/data1/home/sunyiq/us_source_format_runtime_probe_20261008_001\nFORMAT_JOB_ID=%s\nFORMAT_SUBMITTED_ONCE\n' "$job"
